Q: React Leaflet Material UI divIcon not styled A: <p>Try  changing sx to style :</p>
<pre><code>function LeafletMarker({ bgcolor }) {
  return (
    &lt;Box
      style={{
        backgroundColor: bgcolor,
        width: &quot;50px&quot;,
        height: &quot;50px&quot;,
        borderRadius: 5,
      }}
    &gt;
      &lt;HomeIcon /&gt;
    &lt;/Box&gt;
  );
}
</code></pre>
<p>And if you want to change the icon color, use fill :</p>
<pre><code>

function LeafletMarker({ bgcolor }) {
  return (
    &lt;Box
      style={{
        backgroundColor: bgcolor,
        width: &quot;50px&quot;,
        height: &quot;50px&quot;,
        borderRadius: 5,
      }}
    &gt;
      &lt;HomeIcon style ={{fill: &quot;red&quot;}} /&gt;
    &lt;/Box&gt;
  );
}

</code></pre>
